def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 100:
        return 'D'

    opp_d = 0
    my_d = 0
    for a, b in history:
        if b == 'D':
            opp_d += 1
        if a == 'D':
            my_d += 1

    if n < 10:
        return 'C'

    recent = history[-5:] if n >= 5 else history
    recent_opp_d = 0
    recent_my_d = 0
    for a, b in recent:
        if b == 'D':
            recent_opp_d += 1
        if a == 'D':
            recent_my_d += 1

    if opp_d > n * 0.6:
        if n % 10 == 0:
            return 'C'
        return 'D'

    if opp_d <= n * 0.15:
        if recent_opp_d > 0 and recent_opp_d <= 2 and recent_my_d == 0:
            return 'D'
        return 'C'

    opp_last = history[-1][1]
    my_last = history[-1][0]

    if opp_last == 'D':
        if history[-2][1] == 'D':
            if recent_opp_d >= 3:
                return 'D'
            if rng.random() < 0.3:
                return 'C'
            return 'D'
        return 'D'
    else:
        if my_last == 'D':
            return 'C'
        return 'C'
